// Pipeline Optimization: Loop Unrolling (4x)
// Reduces control hazards (branches), enables instruction scheduling
// Uses Register Renaming (s0-s3) to break Write-After-Write hazards
void vectorized_sum(float* data, int N) {
    float s0=0.0f, s1=0.0f, s2=0.0f, s3=0.0f;
    int i;
    for (i = 0; i < N - 3; i += 4) {
        s0 += data[i];
        s1 += data[i+1]; // Independent dependency chains
        s2 += data[i+2]; // Allows multiple ALU ops to execute concurrently
        s3 += data[i+3];
    }
    // Cleanup loop omitted
    // Final result: s0 + s1 + s2 + s3
}

